mapper.select:
SELECT blacklist.id, blacklist.black_name, blacklist.black_mobile_phone_hash, blacklist.black_birth_date, blacklist.black_reason, blacklist.black_mode, blacklist.active_yn, blacklist.created_by, blacklist.created_at, blacklist.updated_at, blacklist.expires_at, COUNT(match_log.id) AS match_count FROM admin_blacklist blacklist LEFT JOIN admin_blacklist_match_log match_log ON match_log.blacklist_id = blacklist.id
( blacklist.black_name LIKE CONCAT('%', #{keyword}, '%') OR blacklist.black_reason LIKE CONCAT('%', #{keyword}, '%') OR CAST(blacklist.id AS CHAR) = #{keyword} )
AND blacklist.active_yn = #{activeYn}
AND blacklist.black_mode = #{blackMode}
GROUP BY blacklist.id, blacklist.black_name, blacklist.black_mobile_phone_hash, blacklist.black_birth_date, blacklist.black_reason, blacklist.black_mode, blacklist.active_yn, blacklist.created_by, blacklist.created_at, blacklist.updated_at, blacklist.expires_at ORDER BY blacklist.updated_at DESC, blacklist.id DESC

mapper.update:
UPDATE admin_blacklist
SET
    active_yn = #{activeYn},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT match_log.id, match_log.application_id, match_log.blacklist_id, application.applicant_name, application.document_srl, application.application_status, application.black_mode_applied, match_log.match_type, match_log.action_taken, match_log.matched_at FROM admin_blacklist_match_log match_log INNER JOIN admin_job_application application ON application.id = match_log.application_id
match_log.blacklist_id = #{blacklistId}
ORDER BY match_log.matched_at DESC, match_log.id DESC

SELECT id, admin_user_id, action_type, target_id, action_detail, ip_address, created_at FROM admin_action_log WHERE target_type = 'BLACKLIST'
AND target_id = #{targetId}
ORDER BY created_at DESC, id DESC
